// the same `name` discovered in two different files (e.g. root and local/)
// loads both — they are independently valid — but emits a warning so log
// lines that reference the pack by name aren't silently ambiguous.
func TestLoadPacks_DuplicatePackNamesAcrossFilesWarn(t *testing.T) {
	// Cannot t.Parallel(): replaces the slog default handler.

	dir := t.TempDir()
	mustWrite(t, dir, "shared.yaml", `
name: shared
version: 1.0.0
rules:
  - id: r1
    regex: 'A+'
`)
	if err := os.MkdirAll(filepath.Join(dir, "local"), 0o755); err != nil {
		t.Fatal(err)
	}
	mustWrite(t, filepath.Join(dir, "local"), "shared.yaml", `
name: shared
version: 1.0.0
rules:
  - id: r2
    regex: 'B+'
`)

	var buf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewJSONHandler(&buf, &slog.HandlerOptions{Level: slog.LevelWarn})))
	t.Cleanup(func() { slog.SetDefault(prev) })

	packs, err := LoadPacks(dir)
	if err != nil {
		t.Fatalf("LoadPacks: %v", err)
	}
	if len(packs) != 2 {
		t.Fatalf("packs: want 2 (both load despite name collision), have %d", len(packs))
	}
	logs := buf.String()
	if !strings.Contains(logs, `"name":"shared"`) {
		t.Errorf("warn should mention duplicated pack name, got: %s", logs)
	}
	if !strings.Contains(logs, "duplicate redactor pack name") {
		t.Errorf("warn should flag duplicate pack name, got: %s", logs)
	}
}

